<?php else: ?><section class="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><form method="get" action="/availability" class="flex flex-wrap items-end gap-3"><label class="block text-sm font-medium">Teacher<select name="teacher_id" onchange="this.form.submit()" class="mt-1.5 block min-w-64 rounded-lg border border-slate-300 bg-white px-3 py-2.5 font-normal"><?php foreach ($teachers as $teacher): ?><option value="<?= (int) $teacher['id'] ?>" <?= (int) $teacher['id'] === $teacherId ? 'selected' : '' ?>><?= $e($teacher['first_name'] . ' ' . $teacher['last_name']) ?></option><?php endforeach; ?></select></label><p class="text-sm text-slate-500">Available is the default. Mark unavailable periods or preferred times.</p></form></section>
