<?php else: ?><form method="post" action="/availability/save"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="teacher_id" value="<?= (int) $teacherId ?>"><section class="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><div class="border-b border-slate-100 px-5 py-4"><h2 class="font-semibold"><?= $selectedTeacher ? $e($selectedTeacher['first_name'] . ' ' . $selectedTeacher['last_name']) : '' ?> availability matrix</h2><p class="mt-1 text-sm text-slate-500">Preferences help the optimiser place lessons. Unavailable periods are treated as hard constraints.</p></div><div class="overflow-x-auto"><table class="w-full min-w-[700px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-3">Day</th><?php foreach ($slots as $slot): ?><th class="px-3 py-3"><span class="block"><?= $e($slot['label']) ?></span><span class="mt-1 block font-normal normal-case"><?= $e(substr((string) $slot['starts_at'], 0, 5)) ?>-<?= $e(substr((string) $slot['ends_at'], 0, 5)) ?></span></th><?php endforeach; ?></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($days as $day): ?><tr><th scope="row" class="px-5 py-3 font-medium"><?= $e($day['name']) ?></th><?php foreach ($slots as $slot): $status = $availability[(int) $day['id']][(int) $slot['id']] ?? 'available'; ?><td class="px-3 py-2"><label class="sr-only" for="availability-<?= (int) $day['id'] ?>-<?= (int) $slot['id'] ?>"><?= $e($day['name'] . ', ' . $slot['label']) ?> availability</label><select id="availability-<?= (int) $day['id'] ?>-<?= (int) $slot['id'] ?>" name="availability[<?= (int) $day['id'] ?>][<?= (int) $slot['id'] ?>]" class="w-full rounded-md border border-slate-200 bg-white px-2 py-2 text-xs"><option value="available" <?= $status === 'available' ? 'selected' : '' ?>>Available</option><option value="preferred" <?= $status === 'preferred' ? 'selected' : '' ?>>Preferred</option><option value="unavailable" <?= $status === 'unavailable' ? 'selected' : '' ?>>Unavailable</option></select></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div></section><div class="flex justify-end"><button type="submit" class="rounded-lg bg-cyan-700 px-5 py-2.5 text-sm font-semibold text-white hover:bg-cyan-800">Save availability</button></div></form><?php endif; ?>
